"""Chapter XIV review 8–15: triangle images, superpositions and fixed points."""
import argparse
import json
from plane_isometries import candidate
from plane_map_review import position,review
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/congruence-motion-review.json'


def congruent_triangle():
    return review(8,'Образ треугольника','Докажи, что движение отображает треугольник в равный ему треугольник.',
      'Вершины A,B,C переходят в A′,B′,C′. По теореме об отрезке стороны переходят во все три отрезка между образами вершин. Расстояния сохраняются, поэтому три стороны нового треугольника по парам равны сторонам исходного, и треугольники равны по третьему признаку. Условие строгого неравенства треугольника сохраняется, поэтому образы вершин не лежат на одной прямой. Если рассматриваем также внутренность, заполним её отрезками из A к точкам стороны BC: их образы заполнят весь новый треугольник.',
      [('Сопоставь три вершины','В первом примере треугольник перенесён целиком. Посмотри, куда перешли стороны AB, BC, CA.','Равенство одной пары сторон не определяет целый треугольник.'),
       ('Найди сторону образа','Во втором примере треугольник повёрнут на 90°. У исходной стороны AB разности координат равны 3 и 4. Определи длину A′B′.','Поворот изменяет направление стороны, но сохраняет длину.'),
       ('Проверь все три длины','У третьего треугольника стороны 3, 4 и 5. Он отражён в вертикальной прямой. Найди периметр образа.','Отражение изменило порядок обхода. Это не мешает равенству треугольников.')],
      [position('Стороны движутся вместе','slide',{'A':(0,0),'B':(2,0),'C':(1,2)},(3,1)),position('Поворот стороны AB','turn',{'A':(1,0),'B':(4,4),'C':(1,3)}),position('Треугольник 3, 4, 5','mirror',{'A':(1,0),'B':(5,0),'C':(1,3)})],
      [('Чему равна A′B′ во втором случае?','5','Квадрат длины равен 3²+4².'),('Каков периметр отражённого треугольника?','12','Сложи три неизменившиеся длины.')],
      'Сохранение трёх сторон приводит к третьему признаку равенства треугольников.',
      'Сначала докажи, что стороны переходят в стороны, затем примени признак равенства.',
      'ABC — исходный треугольник, штрихи указывают образы его вершин.',[123])


def overlay():
    return review(9,'Наложение фигур','Что понимают под наложением в этом курсе геометрии и как по нему устанавливают равенство двух фигур?',
      'Наложение — основное понятие. Его свойства задаются аксиомами. При наложении каждой точке плоскости сопоставляется точка той же плоскости. Говорят, что фигуры равны, когда существует наложение, переводящее всю одну фигуру во всю другую. Наглядно это можно представлять как совмещение на прозрачном листе без искажений; зеркальное совмещение также допускается. В главе затем доказано, что класс наложений совпадает с классом движений.',
      [('Укажи соответствие','На первом рисунке один треугольник совмещается с другим переносом. Укажи, какой вершине нового треугольника соответствует каждая старая.','Недостаточно совместить одну или две вершины: надо проверить положение всей фигуры.'),
       ('Проверь масштаб','Во втором рисунке показано предполагаемое совмещение отрезков при растяжении абсциссы вдвое. Исходная длина 2. Найди длину образа и реши, возможно ли такое наложение.','Изменение масштаба может сохранить форму рисунка, но не равенство фигур.'),
       ('Совмести отражённые фигуры','В третьей схеме треугольник зеркально отражён. AB имеет длину 3. Назови длину соответствующей стороны и поясни, почему изменение ориентации само по себе допустимо.','Не требуй одинакового направления обхода у равных треугольников.')],
      [position('Одно совмещение трёх вершин','slide',{'A':(-1,0),'B':(1,0),'C':(0,2)},(3,1)),position('Изменение размера','stretch',{'A':(1,1),'B':(3,1)}),position('Зеркальное наложение','mirror',{'A':(1,0),'B':(4,0),'C':(2,2)})],
      [('Какова длина образа отрезка длины 2 при показанном горизонтальном растяжении?','4','Расстояние удвоилось; это не наложение.'),('Какова длина A′B′ после истинного зеркального наложения?','3','Соответствующая сторона равна AB.')],
      'Равенство фигур определяется существованием наложения, которое переводит одну во всю другую.',
      'Спроси, хватит ли одного способа совмещения для каждой точки исходной фигуры.',
      'Вторая модель показывает контрпример, первая и третья — наложения.',[124])


def distinct_points():
    return review(10,'Почему точки не склеиваются','Докажи, что при наложении различные точки не могут иметь один и тот же образ.',
      'Предположим, что наложение перевело две разные точки A и B в одну точку P. Тогда фигура из двух точек была бы равна фигуре из одной точки. В силу симметричности равенства существовало бы наложение, переводящее одноточечную фигуру обратно в двухточечную. Но точке P при отображении соответствует только один образ: она не может дать сразу и A, и B. Получили противоречие. После доказательства сохранения расстояний тот же вывод можно проверить и иначе: AB>0, тогда как PP=0.',
      [('Подумай об обратном совмещении','В первом примере две разные точки переходят переносом в две разные точки. Если назвать их одинаковой точкой P, обратное совмещение не сможет восстановить обе.','В прямом направлении одно правило может склеить точки. Здесь решающий шаг — симметричность равенства фигур при наложении.'),
       ('Проверь длину','Во втором примере AB=4. Настоящее наложение — полуоборот. Найди расстояние между образами.','Совпавшие образы дали бы нулевое расстояние, что не согласуется с исходными 4.'),
       ('Раздели число образов и длину','В третьей схеме A и B различны, но очень близки: между ними одна единица. Назови количество различных точек в образе множества {A,B}.','Считать нужно количество разных точек, а не длину соединяющего их отрезка.')],
      [position('Два образа при переносе','slide',{'A':(0,0),'B':(2,1)},(3,0)),position('Полуоборот двух точек','half',{'A':(1,1),'B':(5,1)}),position('Соседние точки остаются разными','slide',{'A':(0,1),'B':(1,1)},(2,2))],
      [('Чему равно расстояние между образами во втором примере?','4','Полуоборот сохраняет длину AB.'),('Сколько разных точек содержит образ {A,B} в третьей схеме?','2','Каждая из двух различных точек даёт отличный образ.')],
      'Наложение одной фигуры на другую устанавливает равенство, а равенство фигур симметрично.',
      'Спроси, сколько точек может быть образами одной-единственной точки при обратном совмещении.',
      'Линии AB и A′B′ показывают расстояния между исходными точками и между их образами.',[124])


def overlay_motion():
    return review(11,'Наложение сохраняет расстояния','Почему каждое наложение является движением плоскости? Начни с произвольной пары точек.',
      'По свойствам наложения образ отрезка AB с концами в A и B — равный ему отрезок A′B′ между образами концов. Равные отрезки имеют равные длины, поэтому A′B′=AB для любой пары. При A=B обе длины нулевые. Наложение задаёт отображение плоскости на себя и не склеивает различные точки. Значит, оно является преобразованием, сохраняющим все расстояния; это и есть движение.',
      [('Проверь именно равенство длин','В первом примере отрезки совмещены переносом. По аксиомам наложения важна не только форма отрезка, но и его равенство образу.','Любые два невырожденных отрезка похожи по форме. Для движения нужны равные длины.'),
       ('Рассчитай конкретную пару','Во второй модели у отрезка AB разности координат равны 5 и 12. После наложения найди длину A′B′.','Длина считается по сумме квадратов, а не сумме двух приращений.'),
       ('Проверь совпавшие концы','В третьем рисунке обе буквы A и B обозначают одну точку. Их образы также совпадают. Найди длину A′B′.','Случай A=B не является исключением из равенства расстояний.')],
      [position('Наложение отрезка','slide',{'A':(0,0),'B':(2,2)},(3,0)),position('Расстояние для пары 5 и 12','turn',{'A':(1,0),'B':(6,12)}),position('Совпавшие концы','slide',{'A':(1,2),'B':(1,2)},(3,1))],
      [('Какова длина образа во втором случае?','13','√(25+144)=13.'),('Чему равна длина отрезка между образами совпавших концов?','0','Образ одной исходной точки один.')],
      'Расстояние между точками равно длине соединяющего их отрезка.',
      'Примени свойства наложения к отрезку, выбранному между произвольными точками.',
      'A′ и B′ — образы A и B при одном и том же наложении.',[123,124])


def motion_overlay():
    return review(12,'Движение совпадает с наложением','Докажи обратную теорему: всякое движение плоскости является наложением. Зачем выбрать три неколлинеарные опорные точки?',
      'Движение переводит невырожденный треугольник ABC в равный ему треугольник A′B′C′. Значит, существует наложение, которое совмещает соответствующие вершины. Для любой иной точки плоскости её два возможных образа — при движении и при этом наложении — имеют равные расстояния до каждой из трёх опор A′,B′,C′. Если образы различны, все три опоры лежат на серединном перпендикуляре к отрезку между ними, что противоречит неколлинеарности. Следовательно, образы любой точки совпадают и построенное наложение равно исходному движению.',
      [('Совмести сначала опоры','В первой схеме неколлинеарные вершины определяют треугольник. Движение даёт равный треугольник, поэтому для этих вершин можно подобрать наложение.','Совпадение только на трёх вершинах пока нужно продолжить доказательством для любой точки.'),
       ('Разбери неоднозначность двух опор','Во втором чертеже M=(1;2) и N=(1;−2) зеркальны относительно AB. Первые две опоры их не различают, а C=(0;1) различает. Посчитай CM².','Расстояния к A и B не исключают зеркального второго кандидата.'),
       ('Проверка с другой третьей опорой','В третьей схеме C=(0;5), M и N прежние. Посчитай CN² и сравни с CM²=10.','Третья неколлинеарная точка разрушает равенство всех трёх расстояний для разных кандидатов.')],
      [position('Три соответствующие опоры','slide',{'A':(-1,0),'B':(1,0),'C':(0,2)},(3,1)),candidate('Третья опора C=(0;1)',1),candidate('Новая опора C=(0;5)',5)],
      [('Чему равно CM² при C=(0;1), M=(1;2)?','2','1²+1²=2.'),('Чему равно CN² при C=(0;5), N=(1;−2)?','50','1²+7²=50.')],
      'Множество точек, равноудалённых от двух различных точек, — одна прямая, их серединный перпендикуляр.',
      'Если два предполагаемых образа различны, определи, где должны были бы лежать все три опоры.',
      'Последние две модели показывают двух возможных кандидатов M и N и три опоры A, B, C.',[123,124])


def equality():
    return review(13,'Равенство фигуры своему образу','Верно ли, что при любом движении каждая фигура переходит в равную ей фигуру? Обоснуй вывод для произвольной фигуры.',
      'Да. Всякое движение является наложением. Если движение переводит множество точек F в F′, то это же наложение совмещает F с F′ целиком. По определению равенства фигур они равны. Рассуждение относится и к конечным наборам точек, и к ломаным, и к фигурам с внутренностью. Равная фигура может занимать другое место плоскости.',
      [('Перемести целую фигуру','Первый треугольник сдвинут в новое положение целиком. Для равенства найден один общий перенос всех его точек.','Перенос отдельных точек разными векторами не задаёт общего движения всей фигуры.'),
       ('Различи равенство и совпадение','Во втором рисунке отрезок повернули. AB имеет длину 6 и занимает другое положение. Укажи длину образа.','Фигуры могут быть равны, даже если как множества точек на рисунке они не совпадают.'),
       ('Проверь фигуру из трёх точек','В третьей схеме три вершины отражены. Исходный треугольник имеет стороны 3, 4 и 5. Найди периметр образа и объясни, почему сам по себе равный периметр ещё не доказывал бы равенство любых фигур.','Доказательство для произвольной фигуры даёт общее наложение, а не совпадение одного числового показателя.')],
      [position('Один перенос фигуры','slide',{'A':(0,0),'B':(2,0),'C':(0,2)},(3,1)),position('Отрезок в другом положении','turn',{'A':(1,0),'B':(7,0)}),position('Отражённая фигура','mirror',{'A':(1,0),'B':(4,0),'C':(1,4)})],
      [('Чему равна длина образа во второй модели?','6','Движение сохраняет расстояние.'),('Каков периметр третьего образа?','12','Сложи соответствующие стороны.')],
      'Фигуры равны, если существует наложение, совмещающее одну со всей другой.',
      'Используй теорему о совпадении класса движений и наложений.','Штрихи показывают образы; старое положение может отличаться от нового.',[124])


def fixed_point():
    return review(14,'Неподвижная точка','Как проверить, является ли точка неподвижной при данном преобразовании? Отличи это от перехода всей фигуры в себя.',
      'Точка M неподвижна, когда её образ равен этой же точке M. В координатах должны совпасть обе координаты одновременно. Например, при повороте на 90° центр остаётся на месте, хотя другие точки могут перемещаться по окружности, сохраняющейся как множество. При ненулевом переносе ни одна точка не остаётся на месте.',
      [('Сравни точку и её образ','В первой модели выбрана точка в центре поворота. Она имеет нулевое расстояние до своего образа.','Возвращение фигуры в себя не означает неподвижности каждой отдельной точки.'),
       ('Проверь точку вне центра','Во второй схеме полуоборот вокруг T переводит A на другой конец диаметра. TA=3. Вычисли AA′.','Равны расстояния до центра, но точки на противоположных концах диаметра различны.'),
       ('Исследуй перенос','В третьей модели каждая точка сдвигается на 4 вправо. Сколько неподвижных точек на всей плоскости у этого преобразования?','Не ищи точку, где перенос изменит направление. Вектор один и тот же везде.')],
      [position('Центр остаётся на месте','turn',{'A':(1,1)},(1,1)),position('Разные концы диаметра','half',{'A':(3,0)}),position('Ненулевой перенос','slide',{'A':(1,1),'B':(2,2)},(4,0))],
      [('Чему равно AA′ при TA=3 во второй модели?','6','T — середина AA′.'),('Сколько неподвижных точек у переноса на 4 вправо?','0','Абсцисса каждой точки увеличивается на 4.')],
      'Неподвижность — свойство пары «точка и её преобразование»: при другом преобразовании ответ может измениться.',
      'Для названной точки проверь равенство M′=M.','Совпадающие обозначения собраны у одной точки.',[122,125,126])


def fixed_by_symmetry():
    return review(15,'Неподвижные точки двух симметрий','Укажи все неподвижные точки осевой и центральной симметрии. Почему список полон?',
      'При осевой симметрии все точки оси неподвижны по построению. Для любой точки вне оси расстояние до образа равно удвоенному положительному расстоянию до оси, поэтому других неподвижных точек нет. При центральной симметрии T переходит в себя. Для всякой другой A расстояние AA′=2·TA положительно; значит, неподвижен только центр.',
      [('Отдели ось от её окрестности','В первом чертеже одна точка A лежит на зеркале, другая B — рядом. Проверь, у какой образ совпадает с исходной.','Малая дистанция до оси не даёт неподвижность, если она положительна.'),
       ('Измерь смещение при отражении','Во втором примере A расположена на расстоянии 4 от вертикального зеркала. Вычисли длину AA′.','При отражении A проходит по перпендикуляру до оси и ещё столько же за ось.'),
       ('Сравни с полуоборотом','На третьей схеме A совпала с центром T, B находится в стороне. Укажи количество неподвижных точек всего преобразования.','У полуоборота неподвижна одна точка, а не вся прямая AB.')],
      [position('Точка на оси и точка вне неё','mirror',{'A':(0,1),'B':(2,2)}),position('Расстояние до оси 4','mirror',{'A':(5,1)},(1,0)),position('Совпадение A=T','half',{'A':(1,1),'B':(3,2)},(1,1))],
      [('Чему равно AA′ при расстоянии до зеркала 4?','8','Двойное расстояние до оси.'),('Сколько неподвижных точек у центральной симметрии?','1','Это сам центр.')],
      'Неподвижность равносильна нулевому расстоянию от точки до её образа.',
      'Вырази расстояние до образа через расстояние до оси или центра.',
      'На первых двух моделях выделена ось. На третьей T — центр полуоборота.',[122,123])


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    rows=[congruent_triangle(),overlay(),distinct_points(),overlay_motion(),motion_overlay(),equality(),fixed_point(),fixed_by_symmetry()]
    raw=json.dumps({'bookId':BOOK,'lessons':rows},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==raw
    else:OUT.write_text(raw)
